/* =========================================================================
   AZO Documentgenerator — gedeelde engine
   Wordt geladen door elke documentpagina. Elke pagina roept enkel
   initPage('<doc-id>') aan; alle logica (formulier bouwen, live preview,
   Word-export) zit hier centraal en dus consistent over alle documenten.
   ========================================================================= */

const LOGO_FULL = "assets/azo_full.png";   /* volledige lockup: berg + AZO + tagline — voor topnav/index (relatief pad, prima binnen de webpagina) */
const LOGO_ICON = "assets/azo_icon.png";   /* enkel het bergicoon — voor topnav/index */

/* Data-URI versies: uitsluitend gebruikt IN gerenderde documenten (brief + Word-export).
   Een Word-document dat lokaal wordt opgeslagen kan geen relatief "assets/..."-pad
   terugvinden (vandaar de vroegere "afbeelding kan niet weergegeven worden"-fout).
   Door de afbeelding als data-URI in te bakken, zit ze altijd mee in het bestand. */
const LOGO_FULL_EMBED = "data:image/png;base64,";
const LOGO_ICON_EMBED = "data:image/png;base64,";

/* Groene accentlijnen, VOORAF gerenderd op hun exacte einddoelgrootte
   (600×3 en 600×2 px, effen AZO-groen). Geen enkele CSS-schaling nodig —
   dat is bewust: percentagebreedtes op <img> worden door Word's
   HTML-renderer onvoorspelbaar geïnterpreteerd. Door de afbeelding zelf al
   op de juiste afmeting te zetten, valt die hele foutbron weg: elke
   renderer (browser, LibreOffice, Word) toont het beeld gewoon op zijn
   eigen pixelgrootte, zoals ook het logo al bewezen betrouwbaar doet. */
const LINE_TOP_EMBED = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAlgAAAADCAIAAADA0uaWAAAAJ0lEQVR42u3VQQEAAATAQBSTTC71BHEXYZ/lbAcAfFUSAGCEAPDUAemnAXk0NlO1AAAAAElFTkSuQmCC";
const LINE_BOTTOM_EMBED = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAlgAAAACCAIAAAALjjUzAAAAIklEQVR42u3QAQEAAAQAIByzzC73DFETytkOAPiqFADw2QGM0AF3iZndkQAAAABJRU5ErkJggg==";

