/* Injecteert DOCUMENT_CSS in de huidige pagina zodat de live preview exact
   dezelfde regels gebruikt als het Word-bestand. Draait één keer bij het
   laden van elke pagina die deze engine gebruikt. */
(function injectDocumentCss(){
  if(typeof document === "undefined") return;
  const style = document.createElement("style");
  style.setAttribute("data-source", "DOCUMENT_CSS");
  style.textContent = DOCUMENT_CSS;
  document.head.appendChild(style);
})();

