/* ---------------------------------------------------------------------
   Kleine helpers
   --------------------------------------------------------------------- */
function esc(s){ return String(s ?? "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
function nl2br(s){ return esc(s).replace(/\n/g,"<br>"); }
function fill(value, placeholder){
  const v = (value ?? "").toString().trim();
  if(!v) return `<span class="field-fill empty" style="background-color:#fbf1de;color:#97662a;font-style:italic;font-weight:bold;padding:0 3px;">${esc(placeholder || "nog in te vullen")}</span>`;
  return `<span class="field-fill" style="color:#1a3d0d;font-weight:bold;">${nl2br(v)}</span>`;
}
const MAANDEN = ["januari","februari","maart","april","mei","juni","juli","augustus","september","oktober","november","december"];
function formatDate(iso){
  if(!iso) return "";
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
  if(!m) return iso;
  const [,y,mo,da] = m;
  return `${parseInt(da,10)} ${MAANDEN[parseInt(mo,10)-1]} ${y}`;
}

/* ---------------------------------------------------------------------
   Bouwstenen van een brief (logo, adresblok, ondertekening, ...)
   --------------------------------------------------------------------- */
function letterhead(refLabel, refValue){
  return `
    <table class="doc-letterhead" width="100%" cellpadding="0" cellspacing="0" border="0">
      <tr>
        <td class="lh-logo-cell" valign="bottom">
          <img src="${LOGO_FULL_EMBED}" alt="AZO — Aankoopcentrale voor Zorg en Overheid" width="80" height="27">
        </td>
        <td class="lh-ref-cell" valign="bottom" align="right">
          <div class="lh-corner-icon"><img src="${LOGO_ICON_EMBED}" alt="" width="17" height="10"></div>
          ${refLabel ? `<div><b>${esc(refLabel)}</b></div>` : ""}
          ${refValue ? `<div>${esc(refValue)}</div>` : `<div>&nbsp;</div>`}
        </td>
      </tr>
    </table>
    <hr class="doc-accent-line" color="#7db73f" size="3" width="100%">
  `;
}
function docFooter(){
  return `
    <hr class="doc-accent-line doc-accent-line-bottom" color="#7db73f" size="2" width="100%">
    <table class="doc-footer" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
      <td class="df-icon" width="3%"><img src="${LOGO_ICON_EMBED}" alt="" width="15" height="9"></td>
      <td class="df-address" align="left"><span class="fg">Vzw Samenaankoop AZO</span> — Torhoutsestraat 338, 8020 Ruddervoorde — info@samenaankoopazo.be</td>
    </tr></table>
  `;
}
/* Rechterkolomblok (venstercouvert-positie), opgebouwd als tabel i.p.v.
   CSS margin-left: dat rendert veel betrouwbaarder in Word/HTML-export. */
function rightColumn(innerHtml){
  return `
    <table class="right-col-table" width="100%" cellpadding="0" cellspacing="0" border="0">
      <tr>
        <td class="right-col-spacer" width="54%">&nbsp;</td>
        <td class="right-col-content" width="46%">${innerHtml}</td>
      </tr>
    </table>
  `;
}

function addressBlock(d){
  return `
    <div class="addr-block">
      <div class="company">${fill(d.bedrijfsnaam, "Naam onderneming")}</div>
      <div>${fill(d.adres1, "Straat en nummer")}</div>
      <div>${fill(d.adres2, "Postcode en plaats")}</div>
    </div>
  `;
}
function signBlock(d){
  return `
    <div class="sign">
      <p>${fill(d.contact_naam)},</p>
      <p>${fill(d.contact_functie)}</p>
    </div>
  `;
}
function contactSentence(d){
  return `Voor bijkomende inlichtingen kan u contact opnemen met ${fill(d.contact_naam)}
    (Samenaankoop AZO vzw – tel. ${fill(d.contact_tel)} – ${fill(d.contact_mail)}).`;
}
function criteriaTable(rows){
  if(!rows || !rows.length){
    return `<p class="field-fill empty" style="display:block;font-family:var(--sans);font-size:9pt;">Nog geen selectiecriteria toegevoegd.</p>`;
  }
  const body = rows.map((r,i) => `
    <tr>
      <td style="width:26pt;">${i+1}</td>
      <td>${fill(r.criterium, "Selectiecriterium")}</td>
      <td>${fill(r.minimum, "Minimumvereiste")}</td>
    </tr>`).join("");
  return `
    <table class="doc-table">
      <thead><tr><th>Nr.</th><th>Selectiecriteria</th><th>Minimumvereisten</th></tr></thead>
      <tbody>${body}</tbody>
    </table>`;
}

function candidatenTable(rows){
  if(!rows || !rows.length){
    return `<p class="field-fill empty" style="display:block;font-family:var(--sans);font-size:9pt;">Nog geen kandidaten toegevoegd.</p>`;
  }
  const body = rows.map((r,i) => `
    <tr>
      <td style="width:20pt;">${i+1}</td>
      <td>${fill(r.naam, "Naam")}</td>
      <td>${fill(r.adres, "Adres")}</td>
      <td style="width:52pt;">${fill(r.postcode, "Postcode")}</td>
      <td>${fill(r.plaats, "Woonplaats")}</td>
      <td>${fill(r.verzendwijze, "Verzendwijze")}</td>
    </tr>`).join("");
  return `
    <table class="doc-table">
      <thead><tr><th>Nr.</th><th>Naam</th><th>Adres</th><th>Postcode</th><th>Woonplaats</th><th>Verzendwijze</th></tr></thead>
      <tbody>${body}</tbody>
    </table>`;
}

function checklistTable(rows){
  if(!rows || !rows.length){
    return `<p class="field-fill empty" style="display:block;font-family:var(--sans);font-size:9pt;">Nog geen nazicht ingevuld.</p>`;
  }
  const body = rows.map(r => `
    <tr>
      <td>${fill(r.naam, "Naam")}</td>
      <td style="width:42pt;">${fill(r.tijdig, "Ja/Nee")}</td>
      <td style="width:42pt;">${fill(r.rsz, "OK")}</td>
      <td style="width:42pt;">${fill(r.fiscaal, "OK")}</td>
      <td style="width:42pt;">${fill(r.juridisch, "OK")}</td>
      <td style="width:48pt;">${fill(r.financieel, "OK")}</td>
      <td style="width:48pt;">${fill(r.technisch, "OK")}</td>
    </tr>`).join("");
  return `
    <table class="doc-table doc-table-checklist">
      <thead><tr><th>Naam</th><th>Tijdig</th><th>RSZ</th><th>Fiscaal</th><th>Jurid.</th><th>Financ.</th><th>Techn.</th></tr></thead>
      <tbody>${body}</tbody>
    </table>`;
}

function motiveringTable(rows, emptyText){
  if(!rows || !rows.length){
    return `<p class="field-fill empty" style="display:block;font-family:var(--sans);font-size:9pt;">${esc(emptyText)}</p>`;
  }
  const body = rows.map(r => `
    <tr>
      <td style="width:150pt;"><b>${fill(r.naam, "Naam")}</b></td>
      <td>${nl2br(r.motivering||"") || fill("", "Motivering")}</td>
    </tr>`).join("");
  return `
    <table class="doc-table">
      <thead><tr><th>Naam</th><th>Motivering</th></tr></thead>
      <tbody>${body}</tbody>
    </table>`;
}

